// Interactive evidence lab: official dropout series (DiNIEE) on Georef/IGN province geometry.
// Data is committed under data/ and generated by scripts/build-evidencia.mjs; nothing is fetched live.
import { abandonoMeta, abandonoYears, abandonoPais, abandonoProvincias } from './data/abandono-interanual.mjs?v=34';
import { geoMeta, geoViewBox, provincias } from './data/geo-provincias.mjs?v=34';

const MAX_BUCKETS = 5;
const fmt = value => value == null ? 'sin dato publicado' : value.toLocaleString('es-AR', { maximumFractionDigits: 2 }) + ' %';
const dataYearStart = abandonoYears[0];
const dataYearEnd = abandonoYears.at(-1);

export function mountEvidenceLab(root) {
  if (!root) return;
  const svg = root.querySelector('#evidencia-svg');
  const chart = root.querySelector('#evidencia-chart');
  const tooltip = root.querySelector('#evidencia-tooltip');
  const yearSelect = root.querySelector('#evidencia-year');
  const nameSelect = root.querySelector('#evidencia-jurisdiccion');
  const ranking = root.querySelector('#evidencia-ranking');
  const readout = root.querySelector('#evidencia-readout');
  const legend = root.querySelector('#evidencia-legend');
  const tableBody = root.querySelector('#evidencia-tabla-body');
  const tableSummary = root.querySelector('#evidencia-tabla-summary');
  const sourceNote = root.querySelector('#evidencia-source');
  const chartSummary = root.querySelector('#evidencia-chart-summary');
  const chartCaption = root.querySelector('#evidencia-serie-title');
  if (!svg || !chart || !yearSelect || !nameSelect || !ranking || !readout) return;

  const state = { nivel: 'secundaria', vista: 'areas', year: abandonoYears.length - 1, id: '06' };
  const byId = new Map(provincias.map(p => [p.id, p]));
  const series = id => abandonoProvincias[id]?.[state.nivel] ?? [];
  const domainMax = () => {
    const values = Object.values(abandonoProvincias).flatMap(p => p[state.nivel]).filter(v => v != null);
    const national = abandonoPais[state.nivel].filter(v => v != null);
    return Math.max(...values, ...national);
  };
  const domainMin = () => {
    const values = Object.values(abandonoProvincias).flatMap(p => p[state.nivel]).filter(v => v != null);
    const national = abandonoPais[state.nivel].filter(v => v != null);
    return Math.min(0, ...values, ...national);
  };
  const bucketOf = (value, max) => value == null ? 'is-nodata' : value < 0 ? 'is-negative' : 'q' + Math.min(MAX_BUCKETS - 1, Math.floor(value / max * MAX_BUCKETS));

  // --- Map paths (built once, re-coloured on state change) ---
  const svgNS = 'http://www.w3.org/2000/svg';
  const paths = new Map();
  const baseGroup = document.createElementNS(svgNS, 'g');
  baseGroup.setAttribute('class', 'ev-basemap');
  const pointsGroup = document.createElementNS(svgNS, 'g');
  pointsGroup.setAttribute('class', 'ev-points');
  for (const province of provincias) {
    const path = document.createElementNS(svgNS, 'path');
    path.setAttribute('d', province.path);
    path.setAttribute('class', 'ev-area');
    path.setAttribute('data-id', province.id);
    path.setAttribute('tabindex', '0');
    path.setAttribute('role', 'button');
    path.addEventListener('pointerenter', () => showTooltip(province.id));
    path.addEventListener('pointermove', moveTooltip);
    path.addEventListener('pointerleave', hideTooltip);
    path.addEventListener('focus', () => showTooltip(province.id, true));
    path.addEventListener('blur', hideTooltip);
    path.addEventListener('click', () => select(province.id));
    path.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); select(province.id); } });
    baseGroup.append(path);
    paths.set(province.id, path);
    const dot = document.createElementNS(svgNS, 'circle');
    dot.setAttribute('class', 'ev-point');
    dot.setAttribute('cx', province.centro[0]);
    dot.setAttribute('cy', province.centro[1]);
    dot.setAttribute('r', '9');
    dot.setAttribute('data-id', province.id);
    const hit = document.createElementNS(svgNS, 'circle');
    hit.setAttribute('class', 'ev-point-hit');
    hit.setAttribute('cx', province.centro[0]);
    hit.setAttribute('cy', province.centro[1]);
    hit.setAttribute('r', '26');
    hit.setAttribute('data-id', province.id);
    hit.addEventListener('pointerenter', () => showTooltip(province.id));
    hit.addEventListener('pointermove', moveTooltip);
    hit.addEventListener('pointerleave', hideTooltip);
    hit.addEventListener('click', () => select(province.id));
    pointsGroup.append(dot, hit);
    province._dot = dot;
  }
  const marker = document.createElementNS(svgNS, 'circle');
  marker.setAttribute('class', 'ev-selected-marker');
  marker.setAttribute('r', '13');
  svg.setAttribute('viewBox', geoViewBox);
  svg.append(baseGroup, pointsGroup, marker);

  // --- Tooltip ---
  function positionTooltip(event) {
    if (!tooltip || !event) return;
    const rect = svg.getBoundingClientRect();
    tooltip.style.left = (event.clientX - rect.left + 14) + 'px';
    tooltip.style.top = (event.clientY - rect.top + 12) + 'px';
  }
  function moveTooltip(event) { positionTooltip(event); }
  function showTooltip(id, fromFocus) {
    if (!tooltip) return;
    const province = byId.get(id);
    const value = series(id)[state.year];
    tooltip.textContent = `${province.nombre.replace('Tierra del Fuego, Antártida e Islas del Atlántico Sur', 'Tierra del Fuego')} · ${fmt(value)} · ${abandonoYears[state.year]}` + (value != null && value < 0 ? ' · valor negativo: ver limitaciones' : '');
    tooltip.hidden = false;
    if (fromFocus) {
      const rect = svg.getBoundingClientRect(), scale = rect.width / svg.viewBox.baseVal.width;
      tooltip.style.left = (province.centro[0] * scale + 16) + 'px';
      tooltip.style.top = (province.centro[1] * scale + 12) + 'px';
    }
  }
  function hideTooltip() { if (tooltip) tooltip.hidden = true; }

  // --- Chart ---
  const chartW = 560, chartH = 240, padL = 40, padR = 14, padT = 16, padB = 30;
  function renderChart() {
    const province = byId.get(state.id);
    const values = series(state.id);
    const national = abandonoPais[state.nivel];
    // The axis must include the published negatives instead of clamping them to the baseline.
    const rawMax = Math.max(4, domainMax());
    const rawMin = domainMin();
    const step = rawMax - rawMin <= 8 ? 2 : 4;
    const max = Math.ceil(rawMax / step) * step;
    const min = Math.floor(rawMin / step) * step;
    const x = index => padL + (chartW - padL - padR) * (index / (abandonoYears.length - 1));
    const y = value => chartH - padB - (chartH - padT - padB) * ((value - min) / (max - min));
    const line = list => list.map((value, index) => value == null ? null : `${x(index).toFixed(1)} ${y(value).toFixed(1)}`).filter(Boolean).join(' L');
    const pieces = [];
    const gridSteps = [];
    for (let value = min; value <= max + 1e-9; value += step) gridSteps.push(value);
    pieces.push(`<g class="ev-chart-grid">${gridSteps.map(value => `<line x1="${padL}" x2="${chartW - padR}" y1="${y(value).toFixed(1)}" y2="${y(value).toFixed(1)}"/><text x="${padL - 8}" y="${(y(value) + 3.5).toFixed(1)}">${value}</text>`).join('')}</g>`);
    abandonoYears.forEach((label, index) => {
      if (label === dataYearStart || label === dataYearEnd || index % 3 === 0) pieces.push(`<text class="ev-chart-x" x="${x(index).toFixed(1)}" y="${chartH - 9}">${label.slice(0, 4)}</text>`);
    });
    pieces.push(`<path class="ev-chart-national" d="M${line(national)}"/>`);
    pieces.push(`<path class="ev-chart-selected" d="M${line(values)}"/>`);
    const points = values.map((value, index) => {
      if (value == null) return '';
      const current = index === state.year;
      return `<g class="ev-chart-point${current ? ' is-current' : ''}" data-year="${index}"><circle class="ev-chart-hit" cx="${x(index).toFixed(1)}" cy="${y(value).toFixed(1)}" r="10"/><circle cx="${x(index).toFixed(1)}" cy="${y(value).toFixed(1)}" r="${current ? 4.6 : 3}"/></g>`;
    }).join('');
    pieces.push(points);
    chart.innerHTML = pieces.join('');
    chart.setAttribute('aria-label', `Serie de abandono interanual, ${state.nivel === 'secundaria' ? 'secundaria' : 'primaria'}, para ${province.nombre}; referencia nacional punteada.`);
    chart.querySelectorAll('.ev-chart-point').forEach(point => point.addEventListener('click', () => { state.year = Number(point.dataset.year); syncControls(); render(); }));
    if (chartSummary) {
      const clean = values.filter(v => v != null);
      const min = Math.min(...clean), maxValue = Math.max(...clean);
      const minYear = abandonoYears[values.indexOf(min)], maxYear = abandonoYears[values.indexOf(maxValue)];
      chartSummary.textContent = `Serie de ${province.nombre} (${state.nivel}): ${fmt(values[0])} en ${dataYearStart}; mínimo ${fmt(min)} en ${minYear}; máximo ${fmt(maxValue)} en ${maxYear}; ${fmt(values.at(-1))} en ${dataYearEnd}. Referencia nacional: ${fmt(national.at(-1))} en ${dataYearEnd}.`;
    }
    if (chartCaption) chartCaption.textContent = province.nombre;
  }

  // --- Ranking, readout, table, legend ---
  function renderRanking() {
    const rows = Object.entries(abandonoProvincias)
      .map(([id, province]) => ({ id, name: province.nombre, value: province[state.nivel][state.year] }))
      .filter(row => row.value != null)
      .sort((a, b) => b.value - a.value);
    const top = rows.slice(0, MAX_BUCKETS);
    const max = Math.max(...rows.map(row => row.value), 1);
    ranking.innerHTML = `<span class="small-mono">MAYORES TASAS · ${abandonoYears[state.year]}</span><ol>${top.map(row => `
      <li><button type="button" data-id="${row.id}" aria-pressed="${row.id === state.id}">
        <span>${row.name}</span><i style="--bar:${(row.value < 0 ? 0 : Math.max(4, row.value / max * 100)).toFixed(1)}%"></i><b>${fmt(row.value)}</b>
      </button></li>`).join('')}</ol>`;
    ranking.querySelectorAll('button').forEach(button => button.addEventListener('click', () => select(button.dataset.id)));
  }
  function renderReadout() {
    const province = byId.get(state.id);
    const values = series(state.id);
    const meta = abandonoProvincias[state.id];
    const clean = values.filter(v => v != null);
    const min = Math.min(...clean), max = Math.max(...clean);
    const delta = values[state.year] != null && values[0] != null ? values[state.year] - values[0] : null;
    const structure = meta?.estructura === '7-5' ? 'primaria de 7 años · secundaria de 5' : 'primaria de 6 años · secundaria de 6';
    readout.innerHTML = `
      <span class="small-mono">JURISDICCIÓN SELECCIONADA</span>
      <h4>${province.nombre.replace('Tierra del Fuego, Antártida e Islas del Atlántico Sur', 'Tierra del Fuego')}</h4>
      <div class="ev-readout-value"><strong>${fmt(values[state.year])}</strong><span>${state.nivel === 'secundaria' ? 'Secundaria' : 'Primaria'} · ${abandonoYears[state.year]}</span></div>
      <dl>
        <div><dt>Δ desde ${dataYearStart}</dt><dd>${delta == null ? 'sin dato' : (delta > 0 ? '+' : '') + delta.toLocaleString('es-AR', { maximumFractionDigits: 2 }) + ' pp'}</dd></div>
        <div><dt>Mínimo de la serie</dt><dd>${fmt(min)} · ${abandonoYears[values.indexOf(min)]}</dd></div>
        <div><dt>Máximo de la serie</dt><dd>${fmt(max)} · ${abandonoYears[values.indexOf(max)]}</dd></div>
        <div><dt>Estructura</dt><dd>${structure}</dd></div>
      </dl>`;
  }
  function renderTable() {
    const rows = Object.entries(abandonoProvincias).map(([id, province]) => {
      const values = province[state.nivel];
      const clean = values.filter(v => v != null);
      return { name: byId.get(id)?.nombre ?? province.nombre, current: values[state.year], min: Math.min(...clean), max: Math.max(...clean), start: values[0] };
    }).sort((a, b) => a.name.localeCompare(b.name, 'es'));
    tableBody.innerHTML = `<table><caption class="sr-only">Tasa de abandono interanual, ${state.nivel}, ${abandonoYears[state.year]}, por jurisdicción</caption><thead><tr><th scope="col">Jurisdicción</th><th scope="col">${abandonoYears[state.year]}</th><th scope="col">${dataYearStart}</th><th scope="col">Mínimo</th><th scope="col">Máximo</th></tr></thead><tbody>${rows.map(row => `<tr><th scope="row">${row.name}</th><td>${fmt(row.current)}</td><td>${fmt(row.start)}</td><td>${fmt(row.min)}</td><td>${fmt(row.max)}</td></tr>`).join('')}</tbody></table>`;
    if (tableSummary) tableSummary.textContent = `Ver los 24 valores publicados · ${state.nivel} · ${abandonoYears[state.year]}`;
  }
  function renderLegend() {
    const max = domainMax();
    const stops = Array.from({ length: MAX_BUCKETS }, (_, index) => `<i class="q${index}" aria-hidden="true"></i>`).join('');
    legend.innerHTML = `<span class="small-mono">TASA ${state.nivel === 'secundaria' ? 'SECUNDARIA' : 'PRIMARIA'} · ${abandonoYears[state.year]}</span>
      <div class="ev-legend-scale"><b>0 %</b>${stops}<b>${Math.ceil(max)} %</b></div>
      <div class="ev-legend-extra"><i class="is-negative" aria-hidden="true"></i> valor negativo (documentado) <i class="is-nodata" aria-hidden="true"></i> sin dato</div>`;
  }
  function renderSource() {
    if (!sourceNote) return;
    sourceNote.innerHTML = `Fuente: DiNIEE · <a href="${abandonoMeta.pagina}" target="_blank" rel="noopener noreferrer">${abandonoMeta.titulo}</a> (planilla «${abandonoMeta.planilla}», ${abandonoMeta.descargado}). Geometrías: <a href="${geoMeta.archivo}" target="_blank" rel="noopener noreferrer">Georef · datos.gob.ar</a> (IGN). Los valores se muestran como se publican, incluidos los negativos que explica el documento de limitaciones; el indicador agrega jurisdicciones y no mide casos individuales.`;
  }

  // --- Map rendering ---
  function renderMap() {
    const max = domainMax();
    const markerProvince = byId.get(state.id);
    svg.classList.toggle('is-points', state.vista === 'puntos');
    for (const province of provincias) {
      const value = abandonoProvincias[province.id]?.[state.nivel]?.[state.year] ?? null;
      const path = paths.get(province.id);
      path.setAttribute('class', 'ev-area ' + bucketOf(value, max) + (province.id === state.id ? ' is-selected' : ''));
      path.setAttribute('aria-label', `${province.nombre.replace('Tierra del Fuego, Antártida e Islas del Atlántico Sur', 'Tierra del Fuego')}: ${fmt(value)} en ${abandonoYears[state.year]}${value != null && value < 0 ? ' (valor negativo publicado)' : ''}. Enter para seleccionar.`);
      const dot = province._dot;
      const radius = value == null ? 7 : 7 + 20 * Math.max(0, Math.min(1, value / max));
      dot.setAttribute('r', radius.toFixed(1));
      dot.setAttribute('class', 'ev-point ' + bucketOf(value, max) + (province.id === state.id ? ' is-selected' : ''));
    }
    marker.setAttribute('cx', markerProvince.centro[0].toFixed(1));
    marker.setAttribute('cy', markerProvince.centro[1].toFixed(1));
    marker.setAttribute('class', 'ev-selected-marker' + (state.vista === 'puntos' ? ' on-points' : ''));
    svg.setAttribute('aria-label', `Mapa de abandono interanual, ${state.nivel}, ${abandonoYears[state.year]}. ${state.vista === 'puntos' ? 'Vista de puntos proporcionales' : 'Vista de áreas'}. Usá las flechas del teclado o la lista de jurisdicciones para recorrer.`);
  }

  function syncControls() {
    root.querySelectorAll('[data-nivel]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.nivel === state.nivel)));
    root.querySelectorAll('[data-vista]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.vista === state.vista)));
    yearSelect.value = String(state.year);
    nameSelect.value = state.id;
  }
  function select(id) { state.id = id; syncControls(); render(); }
  function render() { renderMap(); renderReadout(); renderChart(); renderRanking(); renderTable(); renderLegend(); }

  yearSelect.innerHTML = abandonoYears.map((label, index) => `<option value="${index}">${label}</option>`).reverse().join('');
  nameSelect.innerHTML = provincias.map(province => `<option value="${province.id}">${province.nombre.replace('Tierra del Fuego, Antártida e Islas del Atlántico Sur', 'Tierra del Fuego')}</option>`).join('');
  yearSelect.addEventListener('change', () => { state.year = Number(yearSelect.value); render(); });
  nameSelect.addEventListener('change', () => select(nameSelect.value));
  root.querySelectorAll('[data-nivel]').forEach(button => button.addEventListener('click', () => { state.nivel = button.dataset.nivel; syncControls(); render(); }));
  root.querySelectorAll('[data-vista]').forEach(button => button.addEventListener('click', () => { state.vista = button.dataset.vista; syncControls(); render(); }));
  renderSource();
  syncControls();
  render();
  return { state };
}
